const LANG = 'it';
const IDS = { es: 1056, pt: 708, fr: 673, it: 734, sv: 754, id: 757, ms: 749, th: 753 };
const BASE = 'https://api.lokalise.com/api2/projects/';
const qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_translation_lang_ids=640,' + IDS[LANG];
return [
  { json: { lang: LANG, url: BASE + '31393214664f295f94dd86.76792605/keys?' + qs } },
  { json: { lang: LANG, url: BASE + '9933660066825e9a8005c8.58526829/keys?' + qs } }
];

const LANG = $('Config').first().json.lang;
const PCO = '31393214664f295f94dd86.76792605';
const PROTECT = new Set(['sabrathan@gmail.com','farahputri@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','mteres@terestraducciones.com','arandatrad@gmail.com','sara.guinot.trad@gmail.com','daniel@dgmultilingualservices.com','root-translations@outlook.com','austra.muizniece@gmail.com','harald.roald@gmail.com','47natcha@gmail.com','ellen.de.venter@outlook.com','ilaria.roncaglia@gmail.com','silke.luehrmann@gmx.de','boh.vozniuk@gmail.com','vidiasc@gmail.com','ivanaturcin@ymail.com','julius.valkiunas@gmail.com','jaromirvicari@me.com','karahansisman@gmail.com','katri.varvikko@gmail.com','kenneth@phraseit.dk','translation@cornell.hu','ruckova.lucia@gmail.com','marit.teichmann@gmail.com','michal.tosza@translators.org.pl','mteixeira@sacradomus.com','bruno@bsttranslations.com','nerissaneptuno@gmail.com','straus.translations@gmail.com','quentinnguyen.localize@gmail.com','therese.svardsten@gmail.com','qrcodelocalization@gmail.com','mjlocalize@gmail.com']);
const RX = {
  es: { oa: /\w+o\/a\b|\w+\(a\)/, gratuita: /Prueba gratuita|Test gratuit[ao] de|gratuita de|Pruebas gratuitas|Test de [^\n]{0,40} gratuita\b|Prueba de [^\n]{0,40} gratuita/, tegusto: /Te gusto\b/, mujer: /Arquetipo de (Mujer|Hombre)/, contactanos: /^Contáctanos$/, archivo: /archivo adjunto/ },
  pt: { me: /^"?Me [a-zà-úç]+o\b/, diacritic: /\b(Relatorio|Arquetipo|arquetipo|avaliacao|Tracos|tracos|Traco|traco|neurodivergencia|Neurodivergencia)\b/, neurodiv: /tra[çc]os neurodivergentes|Tra[çc]os Neurodivergentes/i, completando: /completando nosso teste/, crase: /Prefiro [\wà-ú]+ à /, gratuito: /Gratuito\b|^Teste gratuito d/, fico: /^Fico [\wà-ú]+\(a\)/, smart: /eSpecíficas/ },
  fr: { depasse: /dépassée?s?\b|dépassé\(e\)/, gratuit: /^Test gratuit (de|du|des) /, validated: /Cela m'a validé/ },
  it: { rapporto: /\b[Rr]apport[oi]\b/, dei8: /\bdei 8\b/, intuizioni: /\b[Ii]ntuizioni\b/ },
  sv: { klarat: /\bklarat\b/, bpd: /[Bb]orderline personlighetsstörning/, links: /<TermsLink>Användarvillkor|<PrivacyPolicyLink>Integritetspolicy/, mental: /\b[Mm]ental hälsa|\bmentala (och|hälsa)|[Pp]ositiv mental/, forfallna: /förfallna/, prov: /yrkesprov/, karriar: /karriärarketyp/ },
  id: { mistikus: /Mistikus/, laki: /laki-laki/, tagspace: /<\/(TermsLink|PrivacyPolicyLink|link|span)>[a-z]/, expect: /tidak yakin apa yang diharapkan/, kekuatan: /\bkekuatan\b/ },
  ms: { arketipe: /arketipe/i, ndt: /Neurodivergensi/i, terdorong: /\bterdorong\b/, sedia: /\bsedia!/, wawasan: /[Ww]awasan|pandangan arketip/, lengkap: /telah lengkap ujian/ },
  th: { neuro: /ความหลากหลายทางระบบประสาท|ความหลากหลายทางประสาท|ทางประสาท(?!สัมผัส)|นิวโรไดเวอร์เจน|Neurodivergen|ประสาทวิทยา/, more20: /มากกว่า 20/, support: /ได้รับการสนับสนุนโดยค่าธรรมเนียม/, mai: / ๆ/, exact: /ที่แน่นอนของคุณ/, intense: /อารมณ์รุนแรง|ถูกอารมณ์/, calque: /ยากที่จะ|ลำบากที่จะ|หนักใจ|ไขว้เขว|ฉันพบว่า/ }
}[LANG];
const out = { lang: LANG, pages: 0, errors: [], counts: {}, cand: [] };
const seen = {};
for (const it of $input.all()) {
  const r = it.json || {}; const body = r.body || {};
  out.pages++;
  if (!Array.isArray(body.keys)) { out.errors.push({ status: r.statusCode, body: JSON.stringify(body).slice(0, 300) }); continue; }
  const proj = body.project_id === PCO ? 'P' : 'M';
  const c = out.counts[proj] || (out.counts[proj] = { keys: 0, translated: 0, protected: 0, archived: 0, cand: 0 });
  for (const k of body.keys) {
    const sk = proj + k.key_id; if (seen[sk]) continue; seen[sk] = 1;
    c.keys++;
    if (k.is_archived) { c.archived++; continue; }
    let en = '', t = null;
    for (const tr of (k.translations || [])) { const v = typeof tr.translation === 'string' ? tr.translation : JSON.stringify(tr.translation); if (tr.language_iso === 'en') en = v; else t = { v, by: tr.modified_by_email, m: tr.modified_at_timestamp, rev: tr.is_reviewed }; }
    if (!t || !t.v) continue;
    c.translated++;
    if (PROTECT.has(String(t.by).toLowerCase()) || t.rev) { c.protected++; continue; }
    const hits = Object.keys(RX).filter(n => RX[n].test(t.v));
    if (!hits.length) continue;
    c.cand++;
    const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || '') : k.key_name;
    out.cand.push({ p: proj, id: k.key_id, k: name, en, t: t.v, by: t.by, m: t.m, h: hits });
  }
}
return [{ json: out }];
